    if not ((f32_ipv4_udp_length : int) >= 8) then -1
    else if (f32_ipv4_udp_length : int) > n17 then -1
    else off

let[@inline always] check_tcp_cases ~buf ~base ~off ~bw3 ~f6_ipv4_ihl
    ~f9_ipv4_total_length ~f14_ipv4_protocol =
  let[@local] c2_j8 () = check_opaque ~off in
  if (bw3 land 16383 : int) = 0 then
    if (f14_ipv4_protocol : int) = 6 then
      check_tcp ~buf ~base ~off ~f6_ipv4_ihl ~f9_ipv4_total_length
    else if (f14_ipv4_protocol : int) = 17 then
      check_udp ~buf ~base ~off ~f6_ipv4_ihl ~f9_ipv4_total_length
    else c2_j8 ()
  else c2_j8 ()

let[@inline always] check_ipv4 ~buf ~base ~stop ~off =
  if (stop : int) < 34 then -1
  else
    let w14 = Wire_runtime.Unchecked.i64be buf (base + 14) in
    let bw2 = Int64.to_int (Int64.shift_right_logical w14 56) in
    let bw3 = Int64.to_int w14 land 0xffff in
    let f6_ipv4_ihl = bw2 land 0xf in
    if (bw2 : int) < 69 || (bw2 : int) > 79 then -1
    else
      let f9_ipv4_total_length =
        Int64.to_int (Int64.shift_right_logical w14 32) land 0xffff
      in
      if not ((f9_ipv4_total_length : int) >= f6_ipv4_ihl lsl 2) then -1
      else
        let f14_ipv4_protocol = Wire_runtime.Unchecked.u8 buf (base + 23) in
        if (f9_ipv4_total_length : int) > stop - 14 then -1
        else
          check_tcp_cases ~buf ~base ~off ~bw3 ~f6_ipv4_ihl
            ~f9_ipv4_total_length ~f14_ipv4_protocol

let[@inline always] check_record ~buf ~base ~stop ~off =
  if (stop : int) < 14 then -1
  else
    let f3_ether_type = Wire_runtime.Unchecked.u16be buf (base + 12) in
    if (f3_ether_type : int) = 2048 then check_ipv4 ~buf ~base ~stop ~off
    else off

let[@inline always] check (b : 'b Wire_runtime.Buf.t) ~off ~len : 'b check =
  let buf = (b : _ Wire_runtime.Buf.t :> bytes) in
  let length = Bytes.length buf in
  if off < 0 || off > length - len then -1
  else
    let base = off in
    let stop = len in
    check_record ~buf ~base ~stop ~off

let[@inline never] refuse what = invalid_arg (codec_name ^ ": " ^ what)
let[@inline] refuse_if c what = if c then refuse what

let[@inline never] fail at field kind =
  Wire_runtime.Errors.fail { at; field; kind }

let[@inline] eof_if c at expected got field =
  if c then fail at field (Wire_runtime.Error.Unexpected_eof { expected; got })

let[@inline] field_unless c at field v =
  if not c then
    fail at field
      (Wire_runtime.Error.Constraint_failed
         { which = Wire_runtime.Error.Field; value = Some (Int64.of_int v) })

let[@inline] set_bits'u8 (b : _ Wire_runtime.Buf.t) at ~mask ~shift x msg =
  if x land lnot mask <> 0 then invalid_arg msg;
  let buf = (b : _ Wire_runtime.Buf.t :> bytes) in
  let w = Wire_runtime.Unchecked.u8 buf at in
  Wire_runtime.Unchecked.set_u8 buf at
    (w land lnot (mask lsl shift) lor (x lsl shift))

let[@inline] set_bits'u16be (b : _ Wire_runtime.Buf.t) at ~mask ~shift x msg =
  if x land lnot mask <> 0 then invalid_arg msg;
  let buf = (b : _ Wire_runtime.Buf.t :> bytes) in
  let w = Wire_runtime.Unchecked.u16be buf at in
  Wire_runtime.Unchecked.set_u16be buf at
    (w land lnot (mask lsl shift) lor (x lsl shift) land 0xffff)

module Stack_tcp = struct
  type 'b view = int
  type 'b check = int

  let failed = Invalid_argument "Stack_tcp.get: the check failed"
  let[@inline always] is_ok (c : 'b check) = c >= 0

  let[@inline always] get (c : 'b check) : 'b view =
    if c >= 0 then c else raise failed

  let[@inline always] src_port (b : 'b Wire_runtime.Buf.t) (v : 'b view) :
      Wire_runtime.UInt16.t =
    let buf = (b : _ Wire_runtime.Buf.t :> bytes) in
    Wire_runtime.UInt16.unsafe_of_int (Wire_runtime.Unchecked.u16be buf v)

  let[@inline always] dst_port (b : 'b Wire_runtime.Buf.t) (v : 'b view) :
      Wire_runtime.UInt16.t =
    let buf = (b : _ Wire_runtime.Buf.t :> bytes) in
    Wire_runtime.UInt16.unsafe_of_int (Wire_runtime.Unchecked.u16be buf (v + 2))

  let[@inline always] seq (b : 'b Wire_runtime.Buf.t) (v : 'b view) :
      Wire_runtime.UInt32.t =
    let buf = (b : _ Wire_runtime.Buf.t :> bytes) in
    let w4 = Wire_runtime.Unchecked.i64be buf (v + 4) in
    cast uint32_eq (Int64.to_int (Int64.shift_right_logical w4 32))

  let[@inline always] ack (b : 'b Wire_runtime.Buf.t) (v : 'b view) :
      Wire_runtime.UInt32.t =
    let buf = (b : _ Wire_runtime.Buf.t :> bytes) in
    let w8 = Wire_runtime.Unchecked.i64be buf (v + 8) in
    cast uint32_eq (Int64.to_int (Int64.shift_right_logical w8 32))

  let[@inline always] data_offset (b : 'b Wire_runtime.Buf.t) (v : 'b view) :
      int =
    let buf = (b : _ Wire_runtime.Buf.t :> bytes) in
    Wire_runtime.Unchecked.u16be buf (v + 12) lsr 12

  let[@inline always] reserved (b : 'b Wire_runtime.Buf.t) (v : 'b view) : int =
    let buf = (b : _ Wire_runtime.Buf.t :> bytes) in
    (Wire_runtime.Unchecked.u16be buf (v + 12) lsr 9) land 0x7

  let[@inline always] flags (b : 'b Wire_runtime.Buf.t) (v : 'b view) : int =
    let buf = (b : _ Wire_runtime.Buf.t :> bytes) in
    Wire_runtime.Unchecked.u16be buf (v + 12) land 0x1ff

  let[@inline always] window (b : 'b Wire_runtime.Buf.t) (v : 'b view) :
      Wire_runtime.UInt16.t =
    let buf = (b : _ Wire_runtime.Buf.t :> bytes) in
    Wire_runtime.UInt16.unsafe_of_int
      (Wire_runtime.Unchecked.u16be buf (v + 14))

  let[@inline always] checksum (b : 'b Wire_runtime.Buf.t) (v : 'b view) :
      Wire_runtime.UInt16.t =
    let buf = (b : _ Wire_runtime.Buf.t :> bytes) in
    Wire_runtime.UInt16.unsafe_of_int
      (Wire_runtime.Unchecked.u16be buf (v + 16))

  let[@inline always] urgent (b : 'b Wire_runtime.Buf.t) (v : 'b view) :
      Wire_runtime.UInt16.t =
    let buf = (b : _ Wire_runtime.Buf.t :> bytes) in
    Wire_runtime.UInt16.unsafe_of_int
      (Wire_runtime.Unchecked.u16be buf (v + 18))

  let[@inline always] options (b : 'b Wire_runtime.Buf.t) (v : 'b view) :
      Bytesrw.Bytes.Slice.t =
    let buf = (b : _ Wire_runtime.Buf.t :> bytes) in
    let len = Bytes.length buf in
    let bw1 = Wire_runtime.Unchecked.u16be buf (v + 12) in
    let f5_data_offset = bw1 lsr 12 in
    let s2 = (f5_data_offset lsl 2) - 20 in
    if s2 < 0 || s2 > len - (v + 20) then Bytesrw.Bytes.Slice.eod
    else
      let p3 = v + 20 + s2 in
      Bytesrw.Bytes.Slice.make_or_eod buf ~first:(v + 20) ~length:(p3 - (v + 20))

  let[@inline] set_src_port (b : 'b Wire_runtime.Buf.t) (v : 'b view) x =
    let buf = (b : _ Wire_runtime.Buf.t :> bytes) in
    Wire_runtime.Unchecked.set_u16be buf (v + 0)
      ((x : Wire_runtime.UInt16.t :> int) land 0xffff)

  let[@inline] set_dst_port (b : 'b Wire_runtime.Buf.t) (v : 'b view) x =
    let buf = (b : _ Wire_runtime.Buf.t :> bytes) in
    Wire_runtime.Unchecked.set_u16be buf (v + 2)
      ((x : Wire_runtime.UInt16.t :> int) land 0xffff)

  let[@inline] set_seq (b : 'b Wire_runtime.Buf.t) (v : 'b view) x =
    let buf = (b : _ Wire_runtime.Buf.t :> bytes) in
    Wire_runtime.Unchecked.set_i32be buf (v + 4)
      (Wire_runtime.UInt32.to_int32 x)

  let[@inline] set_ack (b : 'b Wire_runtime.Buf.t) (v : 'b view) x =
    let buf = (b : _ Wire_runtime.Buf.t :> bytes) in
    Wire_runtime.Unchecked.set_i32be buf (v + 8)
      (Wire_runtime.UInt32.to_int32 x)

  let[@inline] set_data_offset (b : 'b Wire_runtime.Buf.t) (v : 'b view) x =
    set_bits'u16be b (v + 12) ~mask:0xf ~shift:12 x
      "set_data_offset: the value does not fit in 4 bits"

  let[@inline] set_reserved (b : 'b Wire_runtime.Buf.t) (v : 'b view) x =
    set_bits'u16be b (v + 12) ~mask:0x7 ~shift:9 x
      "set_reserved: the value does not fit in 3 bits"

  let[@inline] set_flags (b : 'b Wire_runtime.Buf.t) (v : 'b view) x =
    set_bits'u16be b (v + 12) ~mask:0x1ff ~shift:0 x
      "set_flags: the value does not fit in 9 bits"

  let[@inline] set_window (b : 'b Wire_runtime.Buf.t) (v : 'b view) x =
    let buf = (b : _ Wire_runtime.Buf.t :> bytes) in
    Wire_runtime.Unchecked.set_u16be buf (v + 14)
      ((x : Wire_runtime.UInt16.t :> int) land 0xffff)

  let[@inline] set_checksum (b : 'b Wire_runtime.Buf.t) (v : 'b view) x =
    let buf = (b : _ Wire_runtime.Buf.t :> bytes) in
    Wire_runtime.Unchecked.set_u16be buf (v + 16)
      ((x : Wire_runtime.UInt16.t :> int) land 0xffff)

  let[@inline] set_urgent (b : 'b Wire_runtime.Buf.t) (v : 'b view) x =
    let buf = (b : _ Wire_runtime.Buf.t :> bytes) in
    Wire_runtime.Unchecked.set_u16be buf (v + 18)
      ((x : Wire_runtime.UInt16.t :> int) land 0xffff)

  type t = {
    src_port : Wire_runtime.UInt16.t;
    dst_port : Wire_runtime.UInt16.t;
    seq : Wire_runtime.UInt32.t;
    ack : Wire_runtime.UInt32.t;
    data_offset : int;
    reserved : int;
    flags : int;
    window : Wire_runtime.UInt16.t;
    checksum : Wire_runtime.UInt16.t;
    urgent : Wire_runtime.UInt16.t;
    options : Bytesrw.Bytes.Slice.t;
  }

  let pp ppf (r : t) =
    let field name pp_v x =
      Format.pp_print_space ppf ();
      Format.pp_print_string ppf (name ^ " = ");
      pp_v ppf x;
      Format.pp_print_char ppf ';'
    in
    Format.pp_open_hvbox ppf 2;
    Format.pp_print_char ppf '{';
    field "src_port" Wire_runtime.UInt16.pp r.src_port;
    field "dst_port" Wire_runtime.UInt16.pp r.dst_port;
    field "seq" Wire_runtime.UInt32.pp r.seq;
    field "ack" Wire_runtime.UInt32.pp r.ack;
    field "data_offset" Format.pp_print_int r.data_offset;
    field "reserved" Format.pp_print_int r.reserved;
    field "flags" Format.pp_print_int r.flags;
    field "window" Wire_runtime.UInt16.pp r.window;
    field "checksum" Wire_runtime.UInt16.pp r.checksum;
    field "urgent" Wire_runtime.UInt16.pp r.urgent;
    field "options"
      (fun ppf s ->
        Format.pp_print_string ppf
          (String.escaped (Bytesrw.Bytes.Slice.to_string s)))
      r.options;
    Format.pp_print_string ppf " }";
    Format.pp_close_box ppf ()

  let of_view (b' : 'b Wire_runtime.Buf.t) (v' : 'b view) : t =
    {
      src_port = src_port b' v';
      dst_port = dst_port b' v';
      seq = seq b' v';
      ack = ack b' v';
      data_offset = data_offset b' v';
      reserved = reserved b' v';
      flags = flags b' v';
      window = window b' v';
      checksum = checksum b' v';
      urgent = urgent b' v';
      options = options b' v';
    }

  let encode_at ~write (r : t) buf p =
    let f1_src_port = (r.src_port : Wire_runtime.UInt16.t :> int) in
    let f2_dst_port = (r.dst_port : Wire_runtime.UInt16.t :> int) in
    let f3_seq = Wire_runtime.UInt32.to_int r.seq in
    let f4_ack = Wire_runtime.UInt32.to_int r.ack in
    let f5_data_offset = r.data_offset in
    let f6_reserved = r.reserved in
    let f7_flags = r.flags in
    let f8_window = (r.window : Wire_runtime.UInt16.t :> int) in
    let f9_checksum = (r.checksum : Wire_runtime.UInt16.t :> int) in
    let f10_urgent = (r.urgent : Wire_runtime.UInt16.t :> int) in
    if write then begin
      Bytes.set_uint16_be buf (p + 0) (f1_src_port land 0xffff);
      Bytes.set_uint16_be buf (p + 2) (f2_dst_port land 0xffff);
      Bytes.set_int32_be buf (p + 4) (Int32.of_int f3_seq);
      Bytes.set_int32_be buf (p + 8) (Int32.of_int f4_ack);
      Wire_runtime.Errors.check_unsigned ~bits:4 f5_data_offset;
      Wire_runtime.Errors.check_unsigned ~bits:3 f6_reserved;
      Wire_runtime.Errors.check_unsigned ~bits:9 f7_flags;
      Bytes.set_uint16_be buf (p + 14) (f8_window land 0xffff);
      Bytes.set_uint16_be buf (p + 16) (f9_checksum land 0xffff);
      Bytes.set_uint16_be buf (p + 18) (f10_urgent land 0xffff);
      Bytes.set_uint16_be buf (p + 12)
        ((f5_data_offset lsl 12) lor (f6_reserved lsl 9) lor (f7_flags lsl 0)
       land 0xffff)
    end;
    let q1 = p + 20 in
    let q3 = (f5_data_offset lsl 2) - 20 in
    refuse_if (q3 < 0) "a negative size";
    refuse_if
      (Bytesrw.Bytes.Slice.length r.options <> q3)
      "a field of bytes does not have its size";
    if write then
      Bytes.blit
        (Bytesrw.Bytes.Slice.bytes r.options)
        (Bytesrw.Bytes.Slice.first r.options)
        buf q1 q3;
    let q2 = q1 + q3 in
    q2

  let size r = encode_at ~write:false r Bytes.empty 0

  let check_pass ~all:_all buf length p0 path =
    if p0 + 14 <= length then begin
      let f5_data_offset =
        (Bytes.get_uint16_be buf (p0 + 12) lsr 12) land 0xf
      in
      field_unless
        ((f5_data_offset : int) >= 5)
        (p0 + 12) (path @ [ "data_offset" ]) f5_data_offset
    end;
    ()

  let[@inline never] error_at buf length p0 path =
    check_pass ~all:false buf length p0 path;
    eof_if (p0 > length - 20) p0 20 (max 0 (length - p0)) path;
    eof_if (p0 + 0 > length - 2) (p0 + 0) 2 (length - (p0 + 0)) path;
    eof_if (p0 + 2 > length - 2) (p0 + 2) 2 (length - (p0 + 2)) path;
    eof_if (p0 + 4 > length - 4) (p0 + 4) 4 (length - (p0 + 4)) path;
    eof_if (p0 + 8 > length - 4) (p0 + 8) 4 (length - (p0 + 8)) path;
    eof_if
      (p0 + 12 > length - 2)
      (p0 + 12) 2
      (length - (p0 + 12))
      (path @ [ "data_offset" ]);
    let f5_data_offset = (Bytes.get_uint16_be buf (p0 + 12) lsr 12) land 0xf in
    field_unless
      ((f5_data_offset : int) >= 5)
      (p0 + 12) (path @ [ "data_offset" ]) f5_data_offset;
    eof_if (p0 + 12 > length - 2) (p0 + 12) 2 (length - (p0 + 12)) path;
    eof_if (p0 + 12 > length - 2) (p0 + 12) 2 (length - (p0 + 12)) path;
    eof_if (p0 + 14 > length - 2) (p0 + 14) 2 (length - (p0 + 14)) path;
    eof_if (p0 + 16 > length - 2) (p0 + 16) 2 (length - (p0 + 16)) path;
    eof_if (p0 + 18 > length - 2) (p0 + 18) 2 (length - (p0 + 18)) path;
    let q1 = p0 + 20 in
    let q3 = (f5_data_offset lsl 2) - 20 in
    eof_if (q3 < 0 || q3 > length - q1) q1 (max 0 q3) (length - q1) path;
    let q2 = q1 + q3 in
    q2
end

module Stack_udp = struct
  type 'b view = int
  type 'b check = int

  let failed = Invalid_argument "Stack_udp.get: the check failed"
  let[@inline always] is_ok (c : 'b check) = c >= 0

  let[@inline always] get (c : 'b check) : 'b view =
    if c >= 0 then c else raise failed

  let[@inline always] src_port (b : 'b Wire_runtime.Buf.t) (v : 'b view) :
      Wire_runtime.UInt16.t =
    let buf = (b : _ Wire_runtime.Buf.t :> bytes) in
    Wire_runtime.UInt16.unsafe_of_int (Wire_runtime.Unchecked.u16be buf v)

  let[@inline always] dst_port (b : 'b Wire_runtime.Buf.t) (v : 'b view) :
      Wire_runtime.UInt16.t =
    let buf = (b : _ Wire_runtime.Buf.t :> bytes) in
    Wire_runtime.UInt16.unsafe_of_int (Wire_runtime.Unchecked.u16be buf (v + 2))

  let[@inline always] length (b : 'b Wire_runtime.Buf.t) (v : 'b view) :
      Wire_runtime.UInt16.t =
