    let q3 = f3_length - 8 in
    refuse_if (q3 < 0) "a negative size";
    refuse_if
      (Bytesrw.Bytes.Slice.length r.payload <> q3)
      "a field of bytes does not have its size";
    if write then
      Bytes.blit
        (Bytesrw.Bytes.Slice.bytes r.payload)
        (Bytesrw.Bytes.Slice.first r.payload)
        buf q1 q3;
    let q2 = q1 + q3 in
    q2

  let size r = encode_at ~write:false r Bytes.empty 0

  let check_pass ~all buf length p0 path =
    if all && p0 + 6 <= length then begin
      let f3_length = Bytes.get_uint16_be buf (p0 + 4) in
      field_unless
        ((f3_length : int) >= 8)
        (p0 + 4) (path @ [ "length" ]) f3_length
    end;
    ()

  let[@inline never] error_at buf length p0 path =
    check_pass ~all:false buf length p0 path;
    eof_if (p0 > length - 8) p0 8 (max 0 (length - p0)) path;
    eof_if (p0 + 0 > length - 2) (p0 + 0) 2 (length - (p0 + 0)) path;
    eof_if (p0 + 2 > length - 2) (p0 + 2) 2 (length - (p0 + 2)) path;
    eof_if
      (p0 + 4 > length - 2)
      (p0 + 4) 2
      (length - (p0 + 4))
      (path @ [ "length" ]);
    let f3_length = Bytes.get_uint16_be buf (p0 + 4) in
    field_unless
      ((f3_length : int) >= 8)
      (p0 + 4) (path @ [ "length" ]) f3_length;
    eof_if (p0 + 6 > length - 2) (p0 + 6) 2 (length - (p0 + 6)) path;
    let q1 = p0 + 8 in
    let q3 = f3_length - 8 in
    eof_if (q3 < 0 || q3 > length - q1) q1 (max 0 q3) (length - q1) path;
    let q2 = q1 + q3 in
    q2
end

module Stack_ipv4 = struct
  type 'b view = int
  type 'b check = int

  let failed = Invalid_argument "Stack_ipv4.get: the check failed"
  let[@inline always] is_ok (c : 'b check) = c >= 0

  let[@inline always] get (c : 'b check) : 'b view =
    if c >= 0 then c else raise failed

  let[@inline never] end_at (buf : bytes) (len : int) (v : int) =
    if v > len - 10 then -1
    else
      let w0 = Wire_runtime.Unchecked.i64be buf v in
      let w2 = Wire_runtime.Unchecked.i64be buf (v + 2) in
      let bw1 = Int64.to_int (Int64.shift_right_logical w0 56) in
      let f2_ihl = bw1 land 0xf in
      let f5_total_length =
        Int64.to_int (Int64.shift_right_logical w0 32) land 0xffff
      in
      let bw2 = Int64.to_int w0 land 0xffff in
      let f10_protocol = Int64.to_int w2 land 0xff in
      let s3 = (f2_ihl lsl 2) - 20 in
      if s3 < 0 || s3 > len - (v + 20) then -1
      else
        let p4 = v + 20 + s3 in
        let p5 =
          if (bw2 land 16383 : int) = 0 && (f10_protocol : int) = 6 then
            let s6 = f5_total_length - (f2_ihl lsl 2) in
            if s6 < 0 || s6 > len - p4 then -1
            else
              let p7 = p4 + s6 in
              p7
          else p4
        in
        if p5 < 0 then -1
        else
          let p8 =
            if (bw2 land 16383 : int) = 0 && (f10_protocol : int) = 17 then
              let s9 = f5_total_length - (f2_ihl lsl 2) in
              if s9 < 0 || s9 > len - p5 then -1
              else
                let p10 = p5 + s9 in
                p10
            else p5
          in
          if p8 < 0 then -1
          else
            let p11 =
              if
                not
                  (((bw2 land 16383 : int) = 0 && (f10_protocol : int) = 6)
                  || ((bw2 land 16383 : int) = 0 && (f10_protocol : int) = 17))
              then
                let s12 = f5_total_length - (f2_ihl lsl 2) in
                if s12 < 0 || s12 > len - p8 then -1
                else
                  let p13 = p8 + s12 in
                  p13
              else p8
            in
            if p11 < 0 then -1 else p11

  let[@inline always] version (b : 'b Wire_runtime.Buf.t) (v : 'b view) : int =
    let buf = (b : _ Wire_runtime.Buf.t :> bytes) in
    Wire_runtime.Unchecked.u8 buf v lsr 4

  let[@inline always] ihl (b : 'b Wire_runtime.Buf.t) (v : 'b view) : int =
    let buf = (b : _ Wire_runtime.Buf.t :> bytes) in
    Wire_runtime.Unchecked.u8 buf v land 0xf

  let[@inline always] dscp (b : 'b Wire_runtime.Buf.t) (v : 'b view) : int =
    let buf = (b : _ Wire_runtime.Buf.t :> bytes) in
    Wire_runtime.Unchecked.u8 buf (v + 1) lsr 2

  let[@inline always] ecn (b : 'b Wire_runtime.Buf.t) (v : 'b view) : int =
    let buf = (b : _ Wire_runtime.Buf.t :> bytes) in
    Wire_runtime.Unchecked.u8 buf (v + 1) land 0x3

  let[@inline always] total_length (b : 'b Wire_runtime.Buf.t) (v : 'b view) :
      Wire_runtime.UInt16.t =
    let buf = (b : _ Wire_runtime.Buf.t :> bytes) in
    Wire_runtime.UInt16.unsafe_of_int (Wire_runtime.Unchecked.u16be buf (v + 2))

  let[@inline always] identification (b : 'b Wire_runtime.Buf.t) (v : 'b view) :
      Wire_runtime.UInt16.t =
    let buf = (b : _ Wire_runtime.Buf.t :> bytes) in
    Wire_runtime.UInt16.unsafe_of_int (Wire_runtime.Unchecked.u16be buf (v + 4))

  let[@inline always] flags (b : 'b Wire_runtime.Buf.t) (v : 'b view) : int =
    let buf = (b : _ Wire_runtime.Buf.t :> bytes) in
    Wire_runtime.Unchecked.u16be buf (v + 6) lsr 13

  let[@inline always] fragment_offset (b : 'b Wire_runtime.Buf.t) (v : 'b view)
      : int =
    let buf = (b : _ Wire_runtime.Buf.t :> bytes) in
    Wire_runtime.Unchecked.u16be buf (v + 6) land 0x1fff

  let[@inline always] ttl (b : 'b Wire_runtime.Buf.t) (v : 'b view) :
      Wire_runtime.UInt8.t =
    let buf = (b : _ Wire_runtime.Buf.t :> bytes) in
    Wire_runtime.UInt8.unsafe_of_int (Wire_runtime.Unchecked.u8 buf (v + 8))

  let[@inline always] protocol (b : 'b Wire_runtime.Buf.t) (v : 'b view) :
      Wire_runtime.UInt8.t =
    let buf = (b : _ Wire_runtime.Buf.t :> bytes) in
    Wire_runtime.UInt8.unsafe_of_int (Wire_runtime.Unchecked.u8 buf (v + 9))

  let[@inline always] checksum (b : 'b Wire_runtime.Buf.t) (v : 'b view) :
      Wire_runtime.UInt16.t =
    let buf = (b : _ Wire_runtime.Buf.t :> bytes) in
    Wire_runtime.UInt16.unsafe_of_int
      (Wire_runtime.Unchecked.u16be buf (v + 10))

  let[@inline always] src (b : 'b Wire_runtime.Buf.t) (v : 'b view) :
      Wire_runtime.UInt32.t =
    let buf = (b : _ Wire_runtime.Buf.t :> bytes) in
    let w12 = Wire_runtime.Unchecked.i64be buf (v + 12) in
    cast uint32_eq (Int64.to_int (Int64.shift_right_logical w12 32))

  let[@inline always] dst (b : 'b Wire_runtime.Buf.t) (v : 'b view) :
      Wire_runtime.UInt32.t =
    let buf = (b : _ Wire_runtime.Buf.t :> bytes) in
    let w12 = Wire_runtime.Unchecked.i64be buf (v + 12) in
    cast uint32_eq (Int64.to_int w12 land mask32)

  let[@inline always] options (b : 'b Wire_runtime.Buf.t) (v : 'b view) :
      Bytesrw.Bytes.Slice.t =
    let buf = (b : _ Wire_runtime.Buf.t :> bytes) in
    let len = Bytes.length buf in
    let bw1 = Wire_runtime.Unchecked.u8 buf v in
    let f2_ihl = bw1 land 0xf in
    let s2 = (f2_ihl lsl 2) - 20 in
    if s2 < 0 || s2 > len - (v + 20) then Bytesrw.Bytes.Slice.eod
    else
