        p4

  let[@inline always] udp (b : 'b Wire_runtime.Buf.t) (v : 'b view) :
      'b Stack_udp.check =
    let buf = (b : _ Wire_runtime.Buf.t :> bytes) in
    let len = Bytes.length buf in
    let w0 = Wire_runtime.Unchecked.i64be buf v in
    let bw1 = Int64.to_int (Int64.shift_right_logical w0 56) in
    let f2_ihl = bw1 land 0xf in
    let bw2 = Int64.to_int w0 land 0xffff in
    let f10_protocol = Wire_runtime.Unchecked.u8 buf (v + 9) in
    if not ((bw2 land 16383 : int) = 0 && (f10_protocol : int) = 17) then -1
    else
      let s3 = (f2_ihl lsl 2) - 20 in
      if s3 < 0 || s3 > len - (v + 20) - 8 then -1
      else
        let p4 = v + 20 + s3 in
        p4

  let[@inline always] opaque_present (b : 'b Wire_runtime.Buf.t) (v : 'b view) :
      bool =
    let buf = (b : _ Wire_runtime.Buf.t :> bytes) in
    let bw1 = Wire_runtime.Unchecked.u16be buf (v + 6) in
    let f10_protocol = Wire_runtime.Unchecked.u8 buf (v + 9) in
    not
      (((bw1 land 16383 : int) = 0 && (f10_protocol : int) = 6)
      || ((bw1 land 16383 : int) = 0 && (f10_protocol : int) = 17))

  let[@inline always] opaque (b : 'b Wire_runtime.Buf.t) (v : 'b view) :
      Bytesrw.Bytes.Slice.t =
    let buf = (b : _ Wire_runtime.Buf.t :> bytes) in
    let len = Bytes.length buf in
    let w0 = Wire_runtime.Unchecked.i64be buf v in
    let bw1 = Int64.to_int (Int64.shift_right_logical w0 56) in
    let f2_ihl = bw1 land 0xf in
    let f5_total_length =
      Int64.to_int (Int64.shift_right_logical w0 32) land 0xffff
    in
    let bw2 = Int64.to_int w0 land 0xffff in
    let f10_protocol = Wire_runtime.Unchecked.u8 buf (v + 9) in
    if
      not
        (not
           (((bw2 land 16383 : int) = 0 && (f10_protocol : int) = 6)
           || ((bw2 land 16383 : int) = 0 && (f10_protocol : int) = 17)))
    then Bytesrw.Bytes.Slice.eod
    else
      let s3 = (f2_ihl lsl 2) - 20 in
      if s3 < 0 || s3 > len - (v + 20) then Bytesrw.Bytes.Slice.eod
      else
        let p4 = v + 20 + s3 in
        let s5 = f5_total_length - (f2_ihl lsl 2) in
        if s5 < 0 || s5 > len - p4 then Bytesrw.Bytes.Slice.eod
        else
          let p6 = p4 + s5 in
          Bytesrw.Bytes.Slice.make_or_eod buf ~first:p4 ~length:(p6 - p4)

  let[@inline] set_version (b : 'b Wire_runtime.Buf.t) (v : 'b view) x =
    set_bits'u8 b (v + 0) ~mask:0xf ~shift:4 x
      "set_version: the value does not fit in 4 bits"

  let[@inline] set_ihl (b : 'b Wire_runtime.Buf.t) (v : 'b view) x =
    set_bits'u8 b (v + 0) ~mask:0xf ~shift:0 x
      "set_ihl: the value does not fit in 4 bits"

  let[@inline] set_dscp (b : 'b Wire_runtime.Buf.t) (v : 'b view) x =
    set_bits'u8 b (v + 1) ~mask:0x3f ~shift:2 x
      "set_dscp: the value does not fit in 6 bits"

  let[@inline] set_ecn (b : 'b Wire_runtime.Buf.t) (v : 'b view) x =
    set_bits'u8 b (v + 1) ~mask:0x3 ~shift:0 x
      "set_ecn: the value does not fit in 2 bits"

  let[@inline] set_total_length (b : 'b Wire_runtime.Buf.t) (v : 'b view) x =
    let buf = (b : _ Wire_runtime.Buf.t :> bytes) in
    Wire_runtime.Unchecked.set_u16be buf (v + 2)
      ((x : Wire_runtime.UInt16.t :> int) land 0xffff)

  let[@inline] set_identification (b : 'b Wire_runtime.Buf.t) (v : 'b view) x =
    let buf = (b : _ Wire_runtime.Buf.t :> bytes) in
    Wire_runtime.Unchecked.set_u16be buf (v + 4)
      ((x : Wire_runtime.UInt16.t :> int) land 0xffff)

  let[@inline] set_flags (b : 'b Wire_runtime.Buf.t) (v : 'b view) x =
    set_bits'u16be b (v + 6) ~mask:0x7 ~shift:13 x
      "set_flags: the value does not fit in 3 bits"

  let[@inline] set_fragment_offset (b : 'b Wire_runtime.Buf.t) (v : 'b view) x =
    set_bits'u16be b (v + 6) ~mask:0x1fff ~shift:0 x
      "set_fragment_offset: the value does not fit in 13 bits"

  let[@inline] set_ttl (b : 'b Wire_runtime.Buf.t) (v : 'b view) x =
    let buf = (b : _ Wire_runtime.Buf.t :> bytes) in
    Wire_runtime.Unchecked.set_u8 buf (v + 8)
      ((x : Wire_runtime.UInt8.t :> int) land 0xff)

  let[@inline] set_protocol (b : 'b Wire_runtime.Buf.t) (v : 'b view) x =
    let buf = (b : _ Wire_runtime.Buf.t :> bytes) in
    Wire_runtime.Unchecked.set_u8 buf (v + 9)
      ((x : Wire_runtime.UInt8.t :> int) land 0xff)

  let[@inline] set_checksum (b : 'b Wire_runtime.Buf.t) (v : 'b view) x =
    let buf = (b : _ Wire_runtime.Buf.t :> bytes) in
    Wire_runtime.Unchecked.set_u16be buf (v + 10)
