  type t = {
    version : int;
    ihl : int;
    dscp : int;
    ecn : int;
    total_length : Wire_runtime.UInt16.t;
    identification : Wire_runtime.UInt16.t;
    flags : int;
    fragment_offset : int;
    ttl : Wire_runtime.UInt8.t;
    protocol : Wire_runtime.UInt8.t;
    checksum : Wire_runtime.UInt16.t;
    src : Wire_runtime.UInt32.t;
    dst : Wire_runtime.UInt32.t;
    options : Bytesrw.Bytes.Slice.t;
    tcp : Stack_tcp.t option;
    udp : Stack_udp.t option;
    opaque : Bytesrw.Bytes.Slice.t option;
  }

  let pp ppf (r : t) =
    let field name pp_v x =
      Format.pp_print_space ppf ();
      Format.pp_print_string ppf (name ^ " = ");
      pp_v ppf x;
      Format.pp_print_char ppf ';'
    in
    Format.pp_open_hvbox ppf 2;
    Format.pp_print_char ppf '{';
    field "version" Format.pp_print_int r.version;
    field "ihl" Format.pp_print_int r.ihl;
    field "dscp" Format.pp_print_int r.dscp;
    field "ecn" Format.pp_print_int r.ecn;
    field "total_length" Wire_runtime.UInt16.pp r.total_length;
    field "identification" Wire_runtime.UInt16.pp r.identification;
    field "flags" Format.pp_print_int r.flags;
    field "fragment_offset" Format.pp_print_int r.fragment_offset;
    field "ttl" Wire_runtime.UInt8.pp r.ttl;
    field "protocol" Wire_runtime.UInt8.pp r.protocol;
    field "checksum" Wire_runtime.UInt16.pp r.checksum;
    field "src" Wire_runtime.UInt32.pp r.src;
    field "dst" Wire_runtime.UInt32.pp r.dst;
    field "options"
      (fun ppf s ->
        Format.pp_print_string ppf
          (String.escaped (Bytesrw.Bytes.Slice.to_string s)))
      r.options;
    field "tcp"
      (fun ppf -> function
        | None -> Format.pp_print_string ppf "None"
        | Some x ->
            Format.pp_print_string ppf "Some (";
            Stack_tcp.pp ppf x;
            Format.pp_print_char ppf ')')
      r.tcp;
    field "udp"
      (fun ppf -> function
        | None -> Format.pp_print_string ppf "None"
        | Some x ->
            Format.pp_print_string ppf "Some (";
            Stack_udp.pp ppf x;
            Format.pp_print_char ppf ')')
      r.udp;
    field "opaque"
      (fun ppf -> function
        | None -> Format.pp_print_string ppf "None"
        | Some x ->
            Format.pp_print_string ppf "Some (";
            (fun ppf s ->
              Format.pp_print_string ppf
                (String.escaped (Bytesrw.Bytes.Slice.to_string s)))
              ppf x;
            Format.pp_print_char ppf ')')
      r.opaque;
    Format.pp_print_string ppf " }";
    Format.pp_close_box ppf ()

  let of_view (b' : 'b Wire_runtime.Buf.t) (v' : 'b view) : t =
    {
      version = version b' v';
      ihl = ihl b' v';
      dscp = dscp b' v';
      ecn = ecn b' v';
      total_length = total_length b' v';
      identification = identification b' v';
      flags = flags b' v';
      fragment_offset = fragment_offset b' v';
      ttl = ttl b' v';
      protocol = protocol b' v';
      checksum = checksum b' v';
      src = src b' v';
      dst = dst b' v';
      options = options b' v';
      tcp =
        (let c = tcp b' v' in
         if Stack_tcp.is_ok c then Some (Stack_tcp.of_view b' (Stack_tcp.get c))
         else None);
      udp =
        (let c = udp b' v' in
         if Stack_udp.is_ok c then Some (Stack_udp.of_view b' (Stack_udp.get c))
         else None);
      opaque = (if opaque_present b' v' then Some (opaque b' v') else None);
    }

  let encode_at'q9 ~write (r : t) buf q2 =
    let f2_ihl = r.ihl in
    let f5_total_length = (r.total_length : Wire_runtime.UInt16.t :> int) in
    let f7_flags = r.flags in
    let f8_fragment_offset = r.fragment_offset in
    let f10_protocol = (r.protocol : Wire_runtime.UInt8.t :> int) in
    match r.tcp with
    | Some q5 ->
        refuse_if
          (not
             (((f7_flags land 1 : int) = 0 && (f8_fragment_offset : int) = 0)
             && (f10_protocol : int) = 6))
          "tcp is absent where its condition holds";
        let q7 = f5_total_length - (f2_ihl lsl 2) in
        refuse_if (q7 < 0) "a negative size";
        let q8 = Stack_tcp.encode_at ~write q5 buf q2 in
        refuse_if (q8 > q2 + q7) "a field does not fill its region";
        if write then Bytes.fill buf q8 (q2 + q7 - q8) '\000';
        let q6 = q2 + q7 in
        q6
    | None ->
        refuse_if
          (((f7_flags land 1 : int) = 0 && (f8_fragment_offset : int) = 0)
          && (f10_protocol : int) = 6)
          "tcp is present where its condition fails";
        q2

  let encode_at'q15 ~write (r : t) buf q4 =
    let f2_ihl = r.ihl in
    let f5_total_length = (r.total_length : Wire_runtime.UInt16.t :> int) in
    let f7_flags = r.flags in
    let f8_fragment_offset = r.fragment_offset in
    let f10_protocol = (r.protocol : Wire_runtime.UInt8.t :> int) in
    match r.udp with
    | Some q11 ->
        refuse_if
          (not
             (((f7_flags land 1 : int) = 0 && (f8_fragment_offset : int) = 0)
             && (f10_protocol : int) = 17))
          "udp is absent where its condition holds";
        let q13 = f5_total_length - (f2_ihl lsl 2) in
        refuse_if (q13 < 0) "a negative size";
        let q14 = Stack_udp.encode_at ~write q11 buf q4 in
        refuse_if (q14 > q4 + q13) "a field does not fill its region";
        if write then Bytes.fill buf q14 (q4 + q13 - q14) '\000';
        let q12 = q4 + q13 in
        q12
    | None ->
        refuse_if
          (((f7_flags land 1 : int) = 0 && (f8_fragment_offset : int) = 0)
          && (f10_protocol : int) = 17)
          "udp is present where its condition fails";
        q4

  let encode_at'q20 ~write (r : t) buf q10 =
    let f2_ihl = r.ihl in
    let f5_total_length = (r.total_length : Wire_runtime.UInt16.t :> int) in
    let f7_flags = r.flags in
    let f8_fragment_offset = r.fragment_offset in
    let f10_protocol = (r.protocol : Wire_runtime.UInt8.t :> int) in
    match r.opaque with
    | Some q17 ->
        refuse_if
          (not
             (not
                (((f7_flags land 1 : int) = 0 && (f8_fragment_offset : int) = 0)
                 && (f10_protocol : int) = 6
                || ((f7_flags land 1 : int) = 0
                   && (f8_fragment_offset : int) = 0)
                   && (f10_protocol : int) = 17)))
          "opaque is absent where its condition holds";
        let q19 = f5_total_length - (f2_ihl lsl 2) in
        refuse_if (q19 < 0) "a negative size";
        refuse_if
          (Bytesrw.Bytes.Slice.length q17 <> q19)
          "a field of bytes does not have its size";
        if write then
          Bytes.blit
            (Bytesrw.Bytes.Slice.bytes q17)
            (Bytesrw.Bytes.Slice.first q17)
            buf q10 q19;
        let q18 = q10 + q19 in
        q18
    | None ->
        refuse_if
          (not
             (((f7_flags land 1 : int) = 0 && (f8_fragment_offset : int) = 0)
              && (f10_protocol : int) = 6
             || ((f7_flags land 1 : int) = 0 && (f8_fragment_offset : int) = 0)
                && (f10_protocol : int) = 17))
          "opaque is present where its condition fails";
        q10

  let encode_at ~write (r : t) buf p =
    let f1_version = r.version in
    let f2_ihl = r.ihl in
    let f3_dscp = r.dscp in
    let f4_ecn = r.ecn in
    let f5_total_length = (r.total_length : Wire_runtime.UInt16.t :> int) in
    let f6_identification = (r.identification : Wire_runtime.UInt16.t :> int) in
    let f7_flags = r.flags in
    let f8_fragment_offset = r.fragment_offset in
    let f9_ttl = (r.ttl : Wire_runtime.UInt8.t :> int) in
    let f10_protocol = (r.protocol : Wire_runtime.UInt8.t :> int) in
    let f11_checksum = (r.checksum : Wire_runtime.UInt16.t :> int) in
    let f12_src = Wire_runtime.UInt32.to_int r.src in
    let f13_dst = Wire_runtime.UInt32.to_int r.dst in
    if write then begin
      Wire_runtime.Errors.check_unsigned ~bits:4 f1_version;
      Wire_runtime.Errors.check_unsigned ~bits:4 f2_ihl;
      Wire_runtime.Errors.check_unsigned ~bits:6 f3_dscp;
      Wire_runtime.Errors.check_unsigned ~bits:2 f4_ecn;
      Bytes.set_uint16_be buf (p + 2) (f5_total_length land 0xffff);
      Bytes.set_uint16_be buf (p + 4) (f6_identification land 0xffff);
      Wire_runtime.Errors.check_unsigned ~bits:3 f7_flags;
      Wire_runtime.Errors.check_unsigned ~bits:13 f8_fragment_offset;
      Bytes.set_uint8 buf (p + 8) (f9_ttl land 0xff);
      Bytes.set_uint8 buf (p + 9) (f10_protocol land 0xff);
      Bytes.set_uint16_be buf (p + 10) (f11_checksum land 0xffff);
      Bytes.set_int32_be buf (p + 12) (Int32.of_int f12_src);
      Bytes.set_int32_be buf (p + 16) (Int32.of_int f13_dst);
      Bytes.set_uint8 buf (p + 0) ((f1_version lsl 4) lor (f2_ihl lsl 0));
      Bytes.set_uint16_be buf (p + 6)
        ((f7_flags lsl 13) lor (f8_fragment_offset lsl 0) land 0xffff);
      Bytes.set_uint8 buf (p + 1) ((f3_dscp lsl 2) lor (f4_ecn lsl 0))
    end;
    let q1 = p + 20 in
    let q3 = (f2_ihl lsl 2) - 20 in
    refuse_if (q3 < 0) "a negative size";
    refuse_if
      (Bytesrw.Bytes.Slice.length r.options <> q3)
      "a field of bytes does not have its size";
    if write then
      Bytes.blit
        (Bytesrw.Bytes.Slice.bytes r.options)
        (Bytesrw.Bytes.Slice.first r.options)
        buf q1 q3;
    let q2 = q1 + q3 in
    let q4 = encode_at'q9 ~write r buf q2 in
    let q10 = encode_at'q15 ~write r buf q4 in
    let q16 = encode_at'q20 ~write r buf q10 in
    q16

  let size r = encode_at ~write:false r Bytes.empty 0

  let check_pass ~all buf length p0 path =
    if p0 + 1 <= length then begin
      let f1_version = (Bytes.get_uint8 buf (p0 + 0) lsr 4) land 0xf in
      field_unless
        ((f1_version : int) = 4)
        (p0 + 0) (path @ [ "version" ]) f1_version
    end;
    if p0 + 1 <= length then begin
      let f2_ihl = (Bytes.get_uint8 buf (p0 + 0) lsr 0) land 0xf in
      field_unless ((f2_ihl : int) >= 5) (p0 + 0) (path @ [ "ihl" ]) f2_ihl
    end;
    if all && p0 + 4 <= length then begin
      let f2_ihl = (Bytes.get_uint8 buf (p0 + 0) lsr 0) land 0xf in
      let f5_total_length = Bytes.get_uint16_be buf (p0 + 2) in
      field_unless
        ((f5_total_length : int) >= f2_ihl lsl 2)
        (p0 + 2)
        (path @ [ "total_length" ])
        f5_total_length
    end;
    ()

  let[@inline never] error_at'q10 buf length _p0 path q2 f2_ihl f5_total_length
      f7_flags f8_fragment_offset f10_protocol =
    if
      ((f7_flags land 1 : int) = 0 && (f8_fragment_offset : int) = 0)
      && (f10_protocol : int) = 6
    then (
      let q6 = f5_total_length - (f2_ihl lsl 2) in
      eof_if
        (q6 < 0 || q6 > length - q2)
        q2 (max 0 q6) (length - q2) (path @ [ "tcp" ]);
      let q7 = min length (q2 + q6) in
      let q8 =
        let length = q7 in
        let q9 = Stack_tcp.error_at buf length q2 (path @ [ "tcp" ]) in
        q9 - q2
      in
      eof_if (q8 > q6) (q2 + min q8 q6) q6 q8 path;
      let q5 = q2 + q6 in
      q5)
    else q2

  let[@inline never] error_at'q17 buf length _p0 path q4 f2_ihl f5_total_length
      f7_flags f8_fragment_offset f10_protocol =
    if
      ((f7_flags land 1 : int) = 0 && (f8_fragment_offset : int) = 0)
      && (f10_protocol : int) = 17
    then (
      let q13 = f5_total_length - (f2_ihl lsl 2) in
      eof_if
        (q13 < 0 || q13 > length - q4)
        q4 (max 0 q13) (length - q4) (path @ [ "udp" ]);
      let q14 = min length (q4 + q13) in
      let q15 =
        let length = q14 in
        let q16 = Stack_udp.error_at buf length q4 (path @ [ "udp" ]) in
        q16 - q4
      in
      eof_if (q15 > q13) (q4 + min q15 q13) q13 q15 path;
      let q12 = q4 + q13 in
      q12)
    else q4

  let[@inline never] error_at'q21 _buf length _p0 path q11 f2_ihl
      f5_total_length f7_flags f8_fragment_offset f10_protocol =
    if
      not
        (((f7_flags land 1 : int) = 0 && (f8_fragment_offset : int) = 0)
         && (f10_protocol : int) = 6
        || ((f7_flags land 1 : int) = 0 && (f8_fragment_offset : int) = 0)
           && (f10_protocol : int) = 17)
    then (
      let q20 = f5_total_length - (f2_ihl lsl 2) in
      eof_if (q20 < 0 || q20 > length - q11) q11 (max 0 q20) (length - q11) path;
      let q19 = q11 + q20 in
      q19)
    else q11

  let[@inline never] error_at buf length p0 path =
    check_pass ~all:false buf length p0 path;
    eof_if (p0 > length - 20) p0 20 (max 0 (length - p0)) path;
    eof_if
      (p0 + 0 > length - 1)
      (p0 + 0) 1
      (length - (p0 + 0))
      (path @ [ "version" ]);
    let f1_version = (Bytes.get_uint8 buf (p0 + 0) lsr 4) land 0xf in
    field_unless
      ((f1_version : int) = 4)
      (p0 + 0) (path @ [ "version" ]) f1_version;
    eof_if
      (p0 + 0 > length - 1)
      (p0 + 0) 1
      (length - (p0 + 0))
      (path @ [ "ihl" ]);
    let f2_ihl = (Bytes.get_uint8 buf (p0 + 0) lsr 0) land 0xf in
    field_unless ((f2_ihl : int) >= 5) (p0 + 0) (path @ [ "ihl" ]) f2_ihl;
    eof_if (p0 + 1 > length - 1) (p0 + 1) 1 (length - (p0 + 1)) path;
    eof_if (p0 + 1 > length - 1) (p0 + 1) 1 (length - (p0 + 1)) path;
    eof_if
      (p0 + 2 > length - 2)
      (p0 + 2) 2
      (length - (p0 + 2))
      (path @ [ "total_length" ]);
    let f5_total_length = Bytes.get_uint16_be buf (p0 + 2) in
    field_unless
      ((f5_total_length : int) >= f2_ihl lsl 2)
      (p0 + 2)
      (path @ [ "total_length" ])
      f5_total_length;
    eof_if (p0 + 4 > length - 2) (p0 + 4) 2 (length - (p0 + 4)) path;
    eof_if (p0 + 6 > length - 2) (p0 + 6) 2 (length - (p0 + 6)) path;
    let f7_flags = (Bytes.get_uint16_be buf (p0 + 6) lsr 13) land 0x7 in
    eof_if (p0 + 6 > length - 2) (p0 + 6) 2 (length - (p0 + 6)) path;
    let f8_fragment_offset =
      (Bytes.get_uint16_be buf (p0 + 6) lsr 0) land 0x1fff
    in
    eof_if (p0 + 8 > length - 1) (p0 + 8) 1 (length - (p0 + 8)) path;
    eof_if (p0 + 9 > length - 1) (p0 + 9) 1 (length - (p0 + 9)) path;
    let f10_protocol = Bytes.get_uint8 buf (p0 + 9) in
    eof_if (p0 + 10 > length - 2) (p0 + 10) 2 (length - (p0 + 10)) path;
    eof_if (p0 + 12 > length - 4) (p0 + 12) 4 (length - (p0 + 12)) path;
    eof_if (p0 + 16 > length - 4) (p0 + 16) 4 (length - (p0 + 16)) path;
    let q1 = p0 + 20 in
    let q3 = (f2_ihl lsl 2) - 20 in
    eof_if (q3 < 0 || q3 > length - q1) q1 (max 0 q3) (length - q1) path;
    let q2 = q1 + q3 in
    let q4 =
      error_at'q10 buf length p0 path q2 f2_ihl f5_total_length f7_flags
        f8_fragment_offset f10_protocol
    in
    let q11 =
      error_at'q17 buf length p0 path q4 f2_ihl f5_total_length f7_flags
        f8_fragment_offset f10_protocol
    in
    let q18 =
      error_at'q21 buf length p0 path q11 f2_ihl f5_total_length f7_flags
        f8_fragment_offset f10_protocol
    in
    q18
end

let failed = Invalid_argument "EthernetStack.get: the check failed"
let[@inline always] is_ok (c : 'b check) = c >= 0

let[@inline always] get (c : 'b check) : 'b view =
  if c >= 0 then c else raise failed

let[@inline never] end_at (buf : bytes) (len : int) (v : int) =
  if v > len - 14 then -1
  else
    let f3_ether_type = Wire_runtime.Unchecked.u16be buf (v + 12) in
    let p1 =
      if (f3_ether_type : int) = 2048 then
        let p2 = Stack_ipv4.end_at buf len (v + 14) in
        if p2 < 0 then -1 else p2
      else v + 14
    in
    if p1 < 0 then -1 else p1

let[@inline always] dst (b : 'b Wire_runtime.Buf.t) (v : 'b view) :
    Bytesrw.Bytes.Slice.t =
  let buf = (b : _ Wire_runtime.Buf.t :> bytes) in
  Bytesrw.Bytes.Slice.make_or_eod buf ~first:v ~length:6

let[@inline always] src (b : 'b Wire_runtime.Buf.t) (v : 'b view) :
    Bytesrw.Bytes.Slice.t =
  let buf = (b : _ Wire_runtime.Buf.t :> bytes) in
  Bytesrw.Bytes.Slice.make_or_eod buf ~first:(v + 6) ~length:6

let[@inline always] ether_type (b : 'b Wire_runtime.Buf.t) (v : 'b view) :
    Wire_runtime.UInt16.t =
  let buf = (b : _ Wire_runtime.Buf.t :> bytes) in
  Wire_runtime.UInt16.unsafe_of_int (Wire_runtime.Unchecked.u16be buf (v + 12))

let[@inline always] ipv4 (b : 'b Wire_runtime.Buf.t) (v : 'b view) :
    'b Stack_ipv4.check =
  let buf = (b : _ Wire_runtime.Buf.t :> bytes) in
  let len = Bytes.length buf in
  let f3_ether_type = Wire_runtime.Unchecked.u16be buf (v + 12) in
  if not ((f3_ether_type : int) = 2048) then -1
  else if v + 14 > len - 20 then -1
  else v + 14

let[@inline] set_ether_type (b : 'b Wire_runtime.Buf.t) (v : 'b view) x =
  let buf = (b : _ Wire_runtime.Buf.t :> bytes) in
  Wire_runtime.Unchecked.set_u16be buf (v + 12)
    ((x : Wire_runtime.UInt16.t :> int) land 0xffff)

type t = {
  dst : Bytesrw.Bytes.Slice.t;
  src : Bytesrw.Bytes.Slice.t;
  ether_type : Wire_runtime.UInt16.t;
  ipv4 : Stack_ipv4.t option;
}

let pp ppf (r : t) =
  let field name pp_v x =
    Format.pp_print_space ppf ();
    Format.pp_print_string ppf (name ^ " = ");
    pp_v ppf x;
    Format.pp_print_char ppf ';'
  in
  Format.pp_open_hvbox ppf 2;
  Format.pp_print_char ppf '{';
  field "dst"
    (fun ppf s ->
      Format.pp_print_string ppf
        (String.escaped (Bytesrw.Bytes.Slice.to_string s)))
    r.dst;
  field "src"
    (fun ppf s ->
      Format.pp_print_string ppf
        (String.escaped (Bytesrw.Bytes.Slice.to_string s)))
    r.src;
  field "ether_type" Wire_runtime.UInt16.pp r.ether_type;
  field "ipv4"
    (fun ppf -> function
      | None -> Format.pp_print_string ppf "None"
      | Some x ->
          Format.pp_print_string ppf "Some (";
          Stack_ipv4.pp ppf x;
          Format.pp_print_char ppf ')')
    r.ipv4;
  Format.pp_print_string ppf " }";
  Format.pp_close_box ppf ()

let of_view (b' : 'b Wire_runtime.Buf.t) (v' : 'b view) : t =
  {
    dst = dst b' v';
    src = src b' v';
    ether_type = ether_type b' v';
    ipv4 =
      (let c = ipv4 b' v' in
       if Stack_ipv4.is_ok c then
         Some (Stack_ipv4.of_view b' (Stack_ipv4.get c))
       else None);
  }

let encode_at'q5 ~write (r : t) buf q1 =
  let f3_ether_type = (r.ether_type : Wire_runtime.UInt16.t :> int) in
  match r.ipv4 with
  | Some q3 ->
      refuse_if
        (not ((f3_ether_type : int) = 2048))
        "ipv4 is absent where its condition holds";
      let q4 = Stack_ipv4.encode_at ~write q3 buf q1 in
      q4
  | None ->
      refuse_if
        ((f3_ether_type : int) = 2048)
        "ipv4 is present where its condition fails";
      q1

let encode_at ~write (r : t) buf p =
  let f3_ether_type = (r.ether_type : Wire_runtime.UInt16.t :> int) in
  if write then begin
    if Bytesrw.Bytes.Slice.length r.dst <> 6 then
      Wire_runtime.Errors.byte_length ~expected:6
        ~actual:(Bytesrw.Bytes.Slice.length r.dst);
    Bytes.blit
      (Bytesrw.Bytes.Slice.bytes r.dst)
      (Bytesrw.Bytes.Slice.first r.dst)
      buf (p + 0) 6;
    if Bytesrw.Bytes.Slice.length r.src <> 6 then
      Wire_runtime.Errors.byte_length ~expected:6
        ~actual:(Bytesrw.Bytes.Slice.length r.src);
    Bytes.blit
      (Bytesrw.Bytes.Slice.bytes r.src)
      (Bytesrw.Bytes.Slice.first r.src)
      buf (p + 6) 6;
    Bytes.set_uint16_be buf (p + 12) (f3_ether_type land 0xffff)
  end;
  let q1 = p + 14 in
  let q2 = encode_at'q5 ~write r buf q1 in
  q2

let size r = encode_at ~write:false r Bytes.empty 0

let check_pass ~all buf length p0 path =
  if p0 + 14 <= length then begin
    let f3_ether_type = Bytes.get_uint16_be buf (p0 + 12) in
    if (f3_ether_type : int) = 2048 then begin
      Stack_ipv4.check_pass ~all buf length (p0 + 14) (path @ [ "ipv4" ])
    end
  end;
  ()

let[@inline never] error_at'q4 buf length _p0 path q1 f3_ether_type =
  if (f3_ether_type : int) = 2048 then
    let q3 = Stack_ipv4.error_at buf length q1 (path @ [ "ipv4" ]) in
    q3
  else q1

let[@inline never] error_at buf length p0 path =
  check_pass ~all:true buf length p0 path;
  eof_if (p0 > length - 14) p0 14 (max 0 (length - p0)) path;
  eof_if (p0 + 0 > length - 6) (p0 + 0) 6 (length - (p0 + 0)) path;
  eof_if (p0 + 6 > length - 6) (p0 + 6) 6 (length - (p0 + 6)) path;
  eof_if (p0 + 12 > length - 2) (p0 + 12) 2 (length - (p0 + 12)) path;
  let f3_ether_type = Bytes.get_uint16_be buf (p0 + 12) in
  let q1 = p0 + 14 in
  let q2 = error_at'q4 buf length p0 path q1 f3_ether_type in
  q2

let min_size = 14

let[@inline never] first_error buf off =
  match error_at buf (Bytes.length buf) off [] with
  | _ -> no_error ()
  | exception exn when Wire_runtime.Errors.is_error exn ->
      Error (Wire_runtime.Errors.error_of exn)

let is_valid buf off =
  off >= 0
  &&
  match Wire_runtime.Buf.v buf with
  | Wire_runtime.Buf.Any b -> is_ok (check b ~off ~len:(Bytes.length buf - off))

let decode buf ~off =
  if off < 0 then Wire_runtime.Errors.negative_offset off;
  match Wire_runtime.Buf.v buf with
  | Wire_runtime.Buf.Any b ->
      let c = check b ~off ~len:(Bytes.length buf - off) in
      if is_ok c then Ok (of_view b (get c)) else first_error buf off

let validate buf ~off =
  if off < 0 then Wire_runtime.Errors.negative_offset off;
  if is_valid buf off then Ok () else first_error buf off

let encode (r : t) buf ~off =
  if off < 0 then Wire_runtime.Errors.negative_offset off;
  let stop = encode_at ~write:true r buf off in
  match Wire_runtime.Buf.v buf with
  | Wire_runtime.Buf.Any b ->
      if not (is_ok (check b ~off ~len:(stop - off))) then
        invalid_arg (codec_name ^ ": the record does not pass its own checks")

let[@inline never] window_error buf off len =
  let length = Bytes.length buf in
  let first = if off < 0 then 0 else if off > length then length else off in
  let stop =
    if len < 0 then first
    else if len > length - first then length
    else first + len
  in
  match validate (Bytes.sub buf first (stop - first)) ~off:0 with
  | Ok () -> no_error ()
  | Error e ->
      { e with Wire_runtime.Error.at = e.Wire_runtime.Error.at + first }

let window_ok buf off len =
  off >= 0 && len >= 0
  && len <= Bytes.length buf - off
  &&
  match Wire_runtime.Buf.v buf with
  | Wire_runtime.Buf.Any b -> is_ok (check b ~off ~len)

let[@inline never] slot_error buf ~stride =
  let n = Bytes.length buf / stride in
  let rec go i =
    if i >= n then no_error ()
    else if window_ok buf (i * stride) stride then go (i + 1)
    else window_error buf (i * stride) stride
  in
  go 0

let[@inline never] frame_error buf ~offs ~lens =
  let rec go i =
    if i >= Array.length offs then no_error ()
    else if window_ok buf offs.(i) lens.(i) then go (i + 1)
    else window_error buf offs.(i) lens.(i)
  in
  go 0

let[@inline] fold (type a) ?stride ?offs ?lens ?invalid buf ~(init : a) ~f :
    (a, Wire_runtime.Error.t * a) result =
  let exception Refused of a in
  let stop acc = raise_notrace (Refused acc) in
  match (stride, offs, lens) with
  | None, None, None ->
      if Option.is_some invalid then
        invalid_arg "EthernetStack.fold: ~invalid with records back to back";
      let length = Bytes.length buf in
      let rec go off acc =
        if off >= length then Ok acc
        else
          match fold_step buf off (length - off) ~init:acc ~f ~invalid:stop with
          | exception Refused acc ->
              Error (window_error buf off (length - off), acc)
          | acc ->
              let next = end_at buf length off in
              if next <= off then Ok acc else go next acc
      in
      go 0 init
  | Some stride, None, None -> (
      if stride <= 0 then
        invalid_arg "EthernetStack.fold: ~stride is not positive";
      let len = Bytes.length buf / stride * stride in
      match invalid with
      | Some invalid ->
          Ok (fold_step_frames buf 0 len ~stride ~init ~f ~invalid)
      | None -> (
          match fold_step_frames buf 0 len ~stride ~init ~f ~invalid:stop with
          | acc -> Ok acc
          | exception Refused acc -> Error (slot_error buf ~stride, acc)))
  | None, Some offs, Some lens -> (
      match invalid with
      | Some invalid -> Ok (fold_step_index buf ~offs ~lens ~init ~f ~invalid)
      | None -> (
          match fold_step_index buf ~offs ~lens ~init ~f ~invalid:stop with
          | acc -> Ok acc
          | exception Refused acc -> Error (frame_error buf ~offs ~lens, acc)))
  | Some _, Some _, _ | Some _, _, Some _ ->
      invalid_arg "EthernetStack.fold: ~stride with ~offs and ~lens"
  | None, Some _, None | None, None, Some _ ->
      invalid_arg "EthernetStack.fold: ~offs without ~lens"
